definition.script:
pipeline {
    agent any

    tools {
        // Install the Maven version configured as "M3" and add it to the path.
        maven 'maven_lts'
    }
    stages {
        stage('inicializo') {
            steps {
                git 'https://github.com/jmagit/demos-devops.git'
            }
        }
        stage('compilo') {
            steps {
                sh "mvn compile"
            }
        }
        stage('test') {
            steps {
                sh 'mvn test'
            }
            post {
                always {
                    junit '**/target/surefire-reports/TEST-*.xml'
                    recordCoverage(tools: [[parser: 'JACOCO']])
                }
            }
        }
        stage('genera') {
            failFast true
            parallel {
                stage('empaqueta') {
                    // when {
                    //     branch 'production' 
                    // }
                    steps {
                        sh 'mvn package -DskipTests'
                    }
                    post {
                        success {
                            archiveArtifacts artifacts: 'target/*.jar', fingerprint: true, followSymlinks: false
                        }
                    }
                }
                stage('documenta') {
                    steps {
                        sh 'mvn site'
                    }
                }
            }
        }
        stage('despliega') {
            steps {
                mail to: 'amd@example.com',
                 subject: "Pendiente de aprobacion el depliege de ${currentBuild.fullDisplayName}",
                 body: "Para la aprobacion entre en ${env.BUILD_URL+'/console'}"
                timeout(time: 3, unit: 'MINUTES') {
                    input cancel: 'Cancelar', message: 'Procedo al despliegue o aborto', ok: 'Aceptar'
                }
                sh 'mvn install -DskipTests'
            }
        }
    }
    post {
        success {
            mail to: 'team@example.com',
                 subject: "OK Pipeline: ${currentBuild.fullDisplayName}",
                 body: "Something in ${env.BUILD_URL}"
        }
        failure {
            mail to: 'team@example.com',
                 subject: "Failed Pipeline: ${currentBuild.fullDisplayName}",
                 body: "Something is wrong with ${env.BUILD_URL}"
        }
    }
    // stages {
    //     stage('Build') {
    //         steps {
    //             // Get some code from a GitHub repository
    //             git 'https://github.com/jglick/simple-maven-project-with-tests.git'

    //             // Run Maven on a Unix agent.
    //             sh "mvn -Dmaven.test.failure.ignore=true clean package"

    //             // To run Maven on a Windows agent, use
    //             // bat "mvn -Dmaven.test.failure.ignore=true clean package"
    //         }

    //         post {
    //             // If Maven was able to run the tests, even if some of the test
    //             // failed, record the test results and archive the jar file.
    //             success {
    //                 junit '**/target/surefire-reports/TEST-*.xml'
    //                 archiveArtifacts 'target/*.jar'
    //             }
    //         }
    //     }
    // }
}
